    # Keep the intended pattern window and translate the uniform lattice
    # background into the neutral output color.
    if len(vals) > 1:
        vals = vals[:-1]
    if vals and len(vals[0]) > 1:
        vals = [row[:-1] for row in vals]

    out = []
